{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "refresh",
    "backend_id": "backend_001",
    "apps_json": [
      {
        "name": "Earnings Command",
        "description": "Symbol-synced earnings review.",
        "tabs": {
          "review": {
            "id": "review",
            "name": "Review",
            "layout": [
              {
                "i": "estimate_revisions",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              },
              {
                "i": "earnings_chart",
                "x": 20,
                "y": 0,
                "w": 12,
                "h": 9,
                "state": {
                  "params": {
                    "symbol": "NVDA"
                  }
                }
              },
              {
                "i": "surprise_metric",
                "x": 32,
                "y": 0,
                "w": 8,
                "h": 6
              }
            ],
            "groups": [
              {
                "name": "Symbol Sync",
                "type": "param",
                "paramName": "symbol",
                "widgetIds": [
                  "estimate_revisions",
                  "earnings_chart"
                ]
              }
            ]
          }
        }
      }
    ],
    "widgets_json": {
      "earnings_chart": {
        "description": "Plotly EPS beat/miss history.",
        "endpoint": "/eps-history",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "EPS History",
        "params": [
          {
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "paramName": "symbol",
            "type": "endpoint",
            "value": "AAPL"
          }
        ],
        "raw": true,
        "type": "chart"
      },
      "estimate_revisions": {
        "data": {
          "table": {
            "columnsDefs": [
              {
                "cellDataType": "text",
                "field": "quarter",
                "headerName": "Quarter"
              },
              {
                "cellDataType": "number",
                "field": "eps_estimate",
                "headerName": "EPS Est"
              },
              {
                "cellDataType": "number",
                "field": "revenue_estimate_b",
                "headerName": "Revenue Est ($B)"
              }
            ]
          }
        },
        "description": "Street estimate revisions by quarter.",
        "endpoint": "/estimate-revisions",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "Estimate Revisions",
        "params": [
          {
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "paramName": "symbol",
            "type": "endpoint",
            "value": "AAPL"
          }
        ],
        "type": "table"
      },
      "surprise_metric": {
        "description": "Average EPS surprise last 4 quarters.",
        "endpoint": "/avg-surprise",
        "gridData": {
          "h": 4,
          "w": 6
        },
        "name": "Avg Surprise",
        "type": "metric"
      }
    }
  }
}
